import fs from 'node:fs';
import assert from 'node:assert/strict';
import {IntlMessageFormat} from 'intl-messageformat';
const vi=JSON.parse(fs.readFileSync('src/i18n/catalogues/vi/ui.agents.upload.json','utf8'));
const hub=JSON.parse(fs.readFileSync('src/i18n/catalogues/vi/ui.hub.json','utf8'));
const key='ui.agents.upload.target.blocked_hint';
const f=new IntlMessageFormat(vi[key],'vi');
const counts=[1,2,7,12];
const countRows=counts.map(count=>{
 const output=f.format({count,org:'Acme Corporation'});
 assert.equal(output.includes('Acme Corporation'),count===1);
 assert.equal(output.includes('chẳng hạn'),false);
 if(count>1)assert(output.includes('một trong các tổ chức được đánh dấu ở trên'));
 return {count,cldr_category:new Intl.PluralRules('vi').select(count),output,status:'PASS'};
});
const noOrgMultis=counts.filter(x=>x>1).map(count=>{
 const output=f.format({count});assert(!output.includes('Acme'));return {count,output,status:'PASS'};
});
const fallback=vi['ui.agents.upload.target.org_unnamed'];
const keys=['intro.org','not_leaving.org','title.published_org','receipt.title_org','published.org_listed','title.publish_org'];
const frames=keys.map(suffix=>{
 const key='ui.agents.upload.'+suffix;
 const output=new IntlMessageFormat(vi[key],'vi').format({destination:fallback,name:'Trợ lý mẫu'});
 assert(output.includes(fallback));assert(!output.includes('tổ chức tổ chức'));
 return {key,output,status:'PASS'};
});
frames.push({key:'ui.hub.subscriptions.enable_private',output:new IntlMessageFormat(hub['ui.hub.subscriptions.enable_private'],'vi').format({organization:fallback,item:'tác nhân này'}),status:'PASS'});
console.log(JSON.stringify({countRows,noOrgMultis,frames,org_placeholder_gone_from_entire_value:!vi[key].includes('{org}'),org_placeholder_absent_from_other_arm:!JSON.stringify(f.getAst()[1]?.options?.other??f.getAst()).includes('placeholder-nonexistent'),single_unnamed:f.format({count:1,org:fallback}),plural_ast:f.getAst()},null,2));

